"""离线统计卡片视图；只渲染共享统计内核结果。"""
TEMPLATE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>薪火 · 知识统计</title><style>
:root{--paper:#f3f5f0;--card:#fff;--ink:#173e33;--muted:#56695f;--line:#dbe4dc;--green:#2d7355;--soft:#e9f1e9;--amber:#89611c;--red:#a64138;--radius:14px}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;font-variant-numeric:tabular-nums}::selection{background:#cce5cc;color:#173e33}main{width:min(1320px,calc(100% - 64px));margin:0 auto;padding:40px 0 32px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:28px}h1{font-size:27px;letter-spacing:-.02em;margin:0 0 5px;font-weight:650}h2{font-size:17px;margin:0 0 20px;font-weight:650}p{margin:0}small,.muted{color:var(--muted);font-size:13px}.header-meta{text-align:right}select{font:inherit;color:var(--ink);border:1px solid var(--line);border-radius:8px;background:var(--card);padding:9px 32px 9px 12px;cursor:pointer}select:focus-visible,button:focus-visible{outline:3px solid #57946f;outline-offset:3px}select:disabled{cursor:default;opacity:.7}.topline{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;gap:24px}.tag{display:inline-block;border:1px solid var(--line);border-radius:6px;font-size:12px;padding:4px 9px;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px 24px;min-width:0}.label{font-size:14px;color:var(--muted)}.number{font-size:38px;line-height:1.3;font-weight:650;letter-spacing:-.025em;margin:12px 0 10px;white-space:nowrap}.number.unknown{font-size:28px;color:var(--amber)}.note{color:var(--muted);font-size:12px;min-height:19px}.card.feature{background:var(--ink);border-color:var(--ink);color:#fff}.feature .label,.feature .note{color:#c6dccd}.feature .tag{color:#c6dccd;border-color:#496356}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.state-list{display:grid;grid-template-columns:repeat(3,1fr);gap:20px 18px}.state strong{display:block;font-size:27px;font-weight:600}.state span{font-size:13px;color:var(--muted)}.state[data-tone="amber"] strong{color:var(--amber)}.state[data-tone="red"] strong{color:var(--red)}.bar{height:7px;border-radius:5px;display:flex;overflow:hidden;margin:22px 0 0;background:var(--soft)}.bar i{display:block;min-width:0}.command-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px 22px}.command{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:0 0 9px;min-width:0}.command span{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.command b{font-size:17px;font-weight:600}.pair{display:flex;justify-content:space-between;align-items:baseline;gap:18px;padding:9px 0}.pair span{color:var(--muted);font-size:13px}.pair b{font-size:18px;font-weight:600}.section-note{margin-top:18px;color:var(--muted);font-size:12px}.empty{color:var(--muted);padding:12px 0;font-size:14px}footer{margin-top:25px;display:flex;justify-content:space-between;gap:24px;font-size:12px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:1050px){main{width:calc(100% - 40px)}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.bottom{grid-template-columns:1fr}.header-meta{max-width:45%}}@media(prefers-reduced-motion:no-preference){.card{animation:arrive .3s cubic-bezier(.16,1,.3,1) both}@keyframes arrive{from{transform:translateY(5px)}to{transform:translateY(0)}}}
</style></head><body><main>
<header><div><h1>薪火 · 知识统计</h1><p class="muted">使用有记录，知识有反馈。</p></div><div class="header-meta"><p class="muted" id="time"></p><p><small>本地离线快照 · 累计观测</small></p></div></header>
<div class="topline"><label>统计范围 <select id="scope"><option value="local">本机统计</option><option value="team">团队统计</option></select></label><span class="tag" id="coverage"></span></div>
<section class="metrics" aria-label="核心统计" id="metrics"></section>
<section class="bottom" aria-label="统计分布">
<article class="card"><h2>知识状态</h2><div id="states" class="state-list"></div><div class="bar" id="statebar" aria-hidden="true"></div><p class="section-note">当前库存互斥计数；待验证与失效知识分别展示。</p></article>
<article class="card"><h2>命令调用</h2><div class="command-grid" id="commands"></div><p class="section-note" id="command-note"></p></article>
<article class="card"><h2>自动演进</h2><div id="evolution"></div><p class="section-note">反馈绑定内容版本与独立任务；晋升和失效保留证据。</p></article>
<article class="card"><h2>Token 与计量</h2><div id="tokens"></div><p class="section-note" id="token-note"></p></article>
</section><footer><span id="footer-note">命中、阅读、采纳与有效反馈分别计数。</span><span>静态快照 · 重新生成后更新</span></footer>
</main><script type="application/json" id="data">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);
const el=(tag,txt,cls)=>{const n=document.createElement(tag);n.textContent=txt;if(cls)n.className=cls;return n};
const fmt=v=>v==null?'未采集':new Intl.NumberFormat('zh-CN').format(v);
const token=v=>v==null?'未采集':v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(1)+'K':fmt(v);
function metric(label,value,note,feature=false,unknown=false){const c=el('article','','card'+(feature?' feature':''));c.append(el('div',label,'label'),el('p',value,'number'+(unknown?' unknown':'')),el('p',note,'note'));$('metrics').append(c)}
function pair(parent,label,value){const r=el('div','','pair');r.append(el('span',label),el('b',value));parent.append(r)}
function render(){const v=data.overview[$('scope').value],u=v.usage;$('metrics').replaceChildren();
metric('调用次数',fmt(v.calls),v.calls_source,true);metric('知识总量',fmt(v.knowledge_total),'当前库存 · 含待验证与失效知识');
metric('命中检索',fmt(v.hit_searches),v.known_searches==null?'团队未采集检索明细':'已知明细 '+fmt(v.known_searches)+' 次 · 命中率 '+(v.hit_rate==null?'未知':v.hit_rate+'%'));
metric(v.updates_label||'更新调用',fmt(v.updates),v.updates_label?'已导入的版本修订事件':v.updates_note||'调用次数 · 不等同于成功变更数');
metric('Token 用量',token(u.total),u.source,false,u.total==null);
metric('Token 净节省',u.saved_tokens==null?'待测':token(u.saved_tokens),u.savings_note,false,u.saved_tokens==null);
const names={verified:'已验证',once:'待验证',staging:'候选验证中',stale:'已失效',archived:'已归档',unknown:'其他状态'},colors=['#35745b','#93b29d','#d5bc83','#b86d64','#b6c0ba','#dbe4dc'];$('states').replaceChildren();$('statebar').replaceChildren();
if(v.knowledge_total==null)$('states').append(el('p','团队快照没有知识库存，未采集。','empty'));else Object.keys(names).forEach((key,i)=>{const r=el('div','','state');r.dataset.tone=key==='stale'?'red':key==='staging'?'amber':'';r.append(el('strong',fmt(v.knowledge[key])),el('span',names[key]));$('states').append(r);const b=document.createElement('i');b.style.width=(v.knowledge_total?v.knowledge[key]/v.knowledge_total*100:0)+'%';b.style.background=colors[i];$('statebar').append(b)});
$('commands').replaceChildren();for(const x of v.commands.slice(0,12)){const r=el('div','','command');r.append(el('span',x.name),el('b',fmt(x.count)));$('commands').append(r)}if(!v.commands.length)$('commands').append(el('p','暂无可用命令统计。','empty'));
$('command-note').textContent=v.calls_source+(v.legacy_calls==null?'':'；历史日志 '+fmt(v.legacy_calls)+' 次单列，不与新口径相加。')+(v.commands.length>12?' 展示调用最多的 12 项。':'');
$('evolution').replaceChildren();pair($('evolution'),'自动晋升',fmt(v.evolution.promoted));pair($('evolution'),'自动失效',fmt(v.evolution.retired));pair($('evolution'),'累计读取',fmt(v.reads));if(v.reuse)pair($('evolution'),'跨成员有效帮助',fmt(v.reuse.helpful_tasks));
$('tokens').replaceChildren();pair($('tokens'),'已观测请求',fmt(u.requests));pair($('tokens'),'输入 / 输出',token(u.fields.input_tokens)+' / '+token(u.fields.output_tokens));pair($('tokens'),'缓存读取',token(u.fields.cache_read_tokens));pair($('tokens'),'缓存创建',token(u.fields.cache_creation_tokens));
$('token-note').textContent='用量为输入＋输出；缓存复用单列，不直接视为 knowbase 净节省。'+(u.complete?'':'缺失字段保留未知；用量为可用来源的观测范围。');
$('coverage').textContent=v.scope+' · '+(v.scope==='团队'?'已导入事件 '+fmt(v.events)+' 条':'检索 '+fmt(v.searches)+' 次 · 缺明细 '+fmt(v.missing_searches)+' 次');}
$('time').textContent='更新于 '+data.generated.replace('T',' ').slice(0,19);if(!data.overview.team){$('scope').querySelector('[value="team"]').disabled=true;}if(data.preview)$('footer-note').textContent='设计预览 · 以下为明确标注的示例数据';$('scope').addEventListener('change',render);render();
</script></body></html>'''
